/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import CapacitorLabColors from "../../src/CapacitorLabColors.js";
import { DielectricScreen } from "../../src/dielectric/DielectricScreen.js";
import { StringManager } from "../../src/i18n/StringManager.js";
import { IntroductionScreen } from "../../src/introduction/IntroductionScreen.js";
import { MultipleCapacitorsScreen } from "../../src/multiple-capacitors/MultipleCapacitorsScreen.js";
import { CapacitorLabPreferencesModel } from "../../src/preferences/CapacitorLabPreferencesModel.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences (wire query-parameter defaults when any are added).
  const simPreferences = new CapacitorLabPreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new IntroductionScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().introductionStringProperty,
      tandem: Tandem.ROOT.createTandem("introductionScreen"),
      backgroundColorProperty: CapacitorLabColors.backgroundColorProperty,
    }),
    new DielectricScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().dielectricStringProperty,
      tandem: Tandem.ROOT.createTandem("dielectricScreen"),
      backgroundColorProperty: CapacitorLabColors.backgroundColorProperty,
    }),
    new MultipleCapacitorsScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().multipleCapacitorsStringProperty,
      tandem: Tandem.ROOT.createTandem("multipleCapacitorsScreen"),
      backgroundColorProperty: CapacitorLabColors.backgroundColorProperty,
    }),
  ];

  return { screens, tracked: { CapacitorLabColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
